import { describe, it, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/index.js'

function listen(app) {
  return new Promise((resolve, reject) => {
    const server = createServer(app)
    server.listen(0, () => {
      const { port } = server.address()
      resolve({ server, port })
    })
    server.on('error', reject)
  })
}

function close(server) {
  return new Promise(resolve => server.close(resolve))
}

describe('F3 — dados iniciais e GET /salas', () => {
  let server, port

  before(async () => {
    ({ server, port } = await listen(createApp()))
  })

  after(() => close(server))

  it('GET /salas com X-Usuario: p-carla retorna 200 com as 4 salas iniciais', async () => {
    const res = await fetch(`http://localhost:${port}/salas`, {
      headers: { 'X-Usuario': 'p-carla' }
    })
    const body = await res.json()
    assert.equal(res.status, 200)
    assert.deepEqual(body, [
      { id: 'auditorio', nome: 'Auditório Central', capacidade: 200 },
      { id: 'sala-101', nome: 'Sala 101', capacidade: 40 },
      { id: 'sala-102', nome: 'Sala 102', capacidade: 40 },
      { id: 'lab-3', nome: 'Laboratório 3', capacidade: 20 }
    ])
  })
})

export const usuarios = [
  { id: 'org-ana', nome: 'Ana Beatriz Lima', papel: 'organizacao' },
  { id: 'org-bruno', nome: 'Bruno Tavares', papel: 'organizacao' },
  { id: 'p-carla', nome: 'Carla Mendes Souza', papel: 'participante' },
  { id: 'p-diego', nome: 'Diego Alves', papel: 'participante' },
  { id: 'p-elisa', nome: 'Elisa Fernandes da Rocha', papel: 'participante' },
  { id: 'p-fabio', nome: 'Fábio Nogueira', papel: 'participante' },
  { id: 'p-gabriela', nome: 'Gabriela Moura Castro', papel: 'participante' },
  { id: 'p-heitor', nome: 'Heitor Campos', papel: 'participante' },
  { id: 'p-isadora', nome: 'Isadora Ribeiro dos Santos', papel: 'participante' },
  { id: 'p-joao', nome: 'João Pedro Martins', papel: 'participante' }
]

export function usuarioExiste(id) {
  return usuarios.some(u => u.id === id)
}

export const salas = [
  { id: 'auditorio', nome: 'Auditório Central', capacidade: 200 },
  { id: 'sala-101', nome: 'Sala 101', capacidade: 40 },
  { id: 'sala-102', nome: 'Sala 102', capacidade: 40 },
  { id: 'lab-3', nome: 'Laboratório 3', capacidade: 20 }
]

export function listarSalas() {
  return salas
}

import express from 'express'
import { pathToFileURL } from 'node:url'
import { usuarioExiste } from './usuarios.js'
import { listarSalas } from './salas.js'

const usuarioDesconhecido = 'USUARIO_DESCONHECIDO'

function identificacao(req, res, next) {
  const id = req.header('X-Usuario')
  if (!id || !usuarioExiste(id)) {
    return res
      .status(401)
      .json({ erro: usuarioDesconhecido, mensagem: 'Usuário desconhecido.' })
  }
  next()
}

export function createApp() {
  const app = express()
  app.get('/salas', identificacao, (_req, res) =>
    res.status(200).json(listarSalas())
  )
  return app
}

const isMain =
  process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href

if (isMain) {
  const port = Number(process.env.PORT ?? 3000)
  createApp().listen(port, () => {
    console.log(`API escutando na porta ${port}`)
  })
}

import express from 'express'
import { pathToFileURL } from 'node:url'
import { usuarioExiste } from './usuarios.js'
import { listarSalas } from './salas.js'

const usuarioDesconhecido = 'USUARIO_DESCONHECIDO'

function identificacao(req, res, next) {
  const id = req.header('X-Usuario')
  if (!id || !usuarioExiste(id)) {
    return res
      .status(401)
      .json({ erro: usuarioDesconhecido, mensagem: 'Usuário desconhecido.' })
  }
  next()
}

function dadosInvalidos(err, _req, res, _next) {
  if (err) {
    return res
      .status(422)
      .json({ erro: 'DADOS_INVALIDOS', mensagem: 'Corpo deve ser JSON válido.' })
  }
  _next()
}

export function createApp() {
  const app = express()
  app.get('/salas', identificacao, (_req, res) =>
    res.status(200).json(listarSalas())
  )
  app.get('/', (_req, res) => res.status(200).end())
  app.get('/teste-protegida', identificacao, (_req, res) => res.status(200).end())
  app.post(
    '/teste-body',
    express.json({ type: '*/*' }),
    dadosInvalidos,
    (_req, res) => res.status(200).end()
  )
  return app
}

const isMain =
  process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href

if (isMain) {
  const port = Number(process.env.PORT ?? 3000)
  createApp().listen(port, () => {
    console.log(`API escutando na porta ${port}`)
  })
}

